// Imports:
import { readFile } from 'node:fs/promises';
import path from 'node:path';

export function mergeConfigs(base, override) {
  const merged = { ...base };
  for (const [key, value] of Object.entries(override)) {
    if (value !== undefined) {
      merged[key] = value;
    }
  }
  return merged;
}

